class FullTextSearchQuery(BaseModel):
    query: str = Field(..., description='Text to search for. It is turned into a tsquery by websearch_to_tsquery() in the language\'s text search configuration, so bare terms are ANDed, "quoted text" matches as a phrase, OR is available and a leading - excludes a term. Query and stored text are stemmed by that same configuration, so one word form finds the others -- but matching stays lexical, not semantic: a word whose stem occurs in no row cannot match it. Input the parser cannot read is not an error, it is ignored. Must not be blank.', title='Query Text')
    where: str | None = Field('tsl_translations.pk > 0', description="SQL WHERE clause, applied before the full text search runs, so it decides which rows are candidates at all. It can name columns of the language-specific search text table (tsl_search_texts_<language>) and of the joined tsl_translations row, with or without the table name in front. A bare `pk`, `created_at` or `updated_at` is the search text table's; the tsl_translations ones are `tsl_pk`, `tsl_created_at` and `tsl_updated_at`, or spell them out as `tsl_translations.pk` and so on. Every other tsl_translations column keeps its own name either way. Three of them are what scopes a search, because together they say where each translated text came from. `tsl_translations.fk_table` is the name of the source table whose attribute is translated -- a logical reference, not a database foreign key -- so `tsl_translations.fk_table = 'cur_curricula'` searches the curricula texts only, while `tsl_translations.fk_table IN ('prj_projects', 'cur_curricula')` and `tsl_translations.fk_table LIKE 'ops%'` widen that to several. `tsl_translations.fk_table_pk` is the primary key (pk) of the row in that source table, so `tsl_translations.fk_table = 'cur_curricula' AND tsl_translations.fk_table_pk = 5` narrows the search to the texts of one single curriculum; it is only meaningful together with `fk_table`, because every source table numbers its rows from 1 and `fk_table_pk = 5` on its own would match one unrelated row per table. `tsl_translations.fk_attribute` is the name of the attribute (column) in the source table whose text is translated, so `tsl_translations.fk_attribute = 'tsl_title'` searches titles and ignores descriptions. The three combine freely, as in `tsl_translations.fk_table = 'ops_operational_skills' AND tsl_translations.fk_attribute = 'tsl_description'`.", title='Where')
    limit: conint(ge=1) | None = Field(25, description='Maximum number of rows to return. Must be 1 or greater.', title='Limit')
    offset: int | None = Field(None, description='Number of rows to skip off the top of the ranking before `limit` is taken. ts_rank is deterministic for a given query and text, so paging is stable as long as the underlying rows do not change.', title='Offset')
    language: TslLanguageType | None = Field('de', description='Language used for translated fields. It selects both which search text table is searched and which Postgres text search configuration (german, french, italian, english) stems the stored text and the query.', title='Language')


