class SemanticSearch(BaseModel):
    query: str = Field(..., description='Text to search for. It is embedded with the same model and dimension as the stored vectors, and the hits are the rows closest to it. Must not be blank.', title='Query Text')
    where: str | None = Field('tsl_translations.pk > 0', description="SQL WHERE clause, applied before the full text search runs, so it decides which rows are candidates at all. It can name columns of the language-specific search text table (tsl_search_texts_<language>) and of the joined tsl_translations row, with or without the table name in front. A bare `pk`, `created_at` or `updated_at` is the search text table's; the tsl_translations ones are `tsl_pk`, `tsl_created_at` and `tsl_updated_at`, or spell them out as `tsl_translations.pk` and so on. Every other tsl_translations column keeps its own name either way. || Three of them are what scopes a search, because together they say where each translated text came from. `tsl_translations.fk_table` is the name of the source table whose attribute is translated -- a logical reference, not a database foreign key -- so `tsl_translations.fk_table = 'cur_curricula'` searches the curricula texts only, and `tsl_translations.fk_table IN ('prj_projects', 'cur_curricula')` or `tsl_translations.fk_table LIKE 'ops%'` widen that to several. || `tsl_translations.fk_table_pk` is the primary key (pk) of the row in that source table, so `tsl_translations.fk_table = 'cur_curricula' AND tsl_translations.fk_table_pk = 5` narrows the search to the texts of one single curriculum. It is only meaningful together with `fk_table`: every source table numbers its rows from 1, so `fk_table_pk = 5` on its own matches one unrelated row per table. || `tsl_translations.fk_attribute` is the name of the attribute (column) in the source table whose text is translated, so `tsl_translations.fk_attribute = 'tsl_title'` searches titles and ignores descriptions. || The three combine freely, e.g. `tsl_translations.fk_table = 'ops_operational_skills' AND tsl_translations.fk_attribute = 'tsl_description'`.", title='Where')
    limit: conint(ge=1) | None = Field(25, description='Maximum number of rows to return. Must be 1 or greater.', title='Limit')
    offset: int | None = Field(None, description='Number of rows to skip off the top of the ranking before `limit` is taken. Note that the ranking is recomputed per request from a freshly embedded query, and two embeddings of the same text are not bit-identical, so rows with near-equal scores can change places between pages.', title='Offset')
    rerank_result: bool | None = Field(True, description='Whether to reorder the hits with the rerank model. The vector search selects the rows first (so `limit` still decides how many are considered), then the rerank model scores the query against each row text and the rows come back in that order, each carrying its `rerank_similarity`. Costs one extra API call.', title='Rerank Result')
    return_vectors: bool | None = Field(False, description='Whether to include the embedding vector of each hit plus the query vector in the response; the vectors are large, so they are left out unless this is set.', title='Return Vectors')
    language: TslLanguageType | None = Field('de', description='Language used for translated fields. It also selects which vector table is searched.', title='Language')
    total: int | None = Field(None, description='Number of rows in the vector table matching `where`, before `limit` is applied: the size of the candidate set the search ran over, not the number of rows returned. Reranking does not change it.', title='Total')
    count: int | None = Field(None, description='Number of rows actually returned in `rows`, never more than `limit`.', title='Count')
    all: int | None = Field(None, description='Number of rows the language vector table offers to search at all, ignoring `where`: the pool `total` was narrowed down from. Rows without a stored vector are left out here too, since the search could never return them, so `all` equals `total` when `where` matches everything.', title='All')
    query_vector: list[float] | None = Field(None, description='Embedding vector of the query text, 2048 dimensions -- the probe each row vector was compared against. Only present when `return_vectors` was requested.', title='Embedding Query Vector')
    rows: list[AppApiSkillsCommandsSemanticSearchModelsDocument] | None = Field(None, description='The matching rows, ordered by descending `similarity` -- or by descending `rerank_similarity` when `rerank_result` was requested. None when nothing matched.', title='Rows')


